    /// <summary>
    /// Declares one lexer rule. Rules are tried in declaration order: when two rules match the
    /// same (longest) length, the one declared first wins. <paramref name="name"/> becomes a
    /// <c>public const int</c> symbol id on the lexer class.
    /// </summary>
