    {
        /// <param name="name">Symbol name; must be a valid C# identifier.</param>
        /// <param name="pattern">Regular expression, or literal text when <paramref name="isLiteral"/> is true.</param>
        /// <param name="isLiteral">Match <paramref name="pattern"/> exactly, with no regex metacharacters.</param>
        public RuleAttribute(string name, string pattern, bool isLiteral) { Name = name; Pattern = pattern; IsLiteral = isLiteral; }
        public RuleAttribute(string name, string pattern) : this(name, pattern, false) { }
        public string Name { get; }
        public string Pattern { get; }
        public bool IsLiteral { get; }
    }

    /// <summary>Optional lexer-wide settings for a class that carries <see cref="RuleAttribute"/>s.</summary>
    [AttributeUsage(AttributeTargets.Class | AttributeTargets.Struct, AllowMultiple = false, Inherited = false)]
    internal sealed class LexerAttribute : Attribute
    {
        /// <summary>
        /// Add a final catch-all <c>ERROR</c> rule so every unit of input lands in some token
        /// (default true). When false, input no rule matches is returned one unit at a time
        /// with symbol -1.
        /// </summary>
        public bool ErrorRule { get; set; } = true;

        /// <summary>
        /// When set, also generate <c>Tokenize(byte[])</c> and <c>Tokenize(Stream)</c> overloads
        /// that run a second DFA directly over bytes in this encoding: "UTF-8", "UTF-16" /
        /// "UTF-16LE" / "UTF-16BE", "UTF-32" / "UTF-32LE" / "UTF-32BE", or any single-byte code
        /// page by name or number ("latin1", "windows-1252", "437", ...).
        /// </summary>
        public string? Encoding { get; set; }

        /// <summary>
        /// When set, also supports unicode characters in character classes, e.g. <c>[[:L:]]</c> for letters, <c>[[:Lu:]]</c> for uppercase letters, etc.
        /// </summary>
        public bool Unicode { get; set; } = false;
    }

    /// <summary>Input encoding for the byte-level tokenizers: how code units are laid out in bytes.</summary>
    internal sealed class UnitEncoding
    {
        public UnitEncoding(Encoding encoding, int unitSize, bool bigEndian)
        {
            Encoding = encoding;
            UnitSize = unitSize;
            BigEndian = bigEndian;
            Preamble = encoding.GetPreamble();
        }

        /// <summary>Used to decode token text.</summary>
        public Encoding Encoding { get; }
        /// <summary>Bytes per code unit: 1, 2 or 4.</summary>
        public int UnitSize { get; }
        public bool BigEndian { get; }
        /// <summary>Byte order mark skipped at the start of input, if present.</summary>
        public byte[] Preamble { get; }

        public static Encoding CodePage(string name)
        {
            System.Text.Encoding.RegisterProvider(CodePagesEncodingProvider.Instance);
            return int.TryParse(name, NumberStyles.None, CultureInfo.InvariantCulture, out int page)
                ? System.Text.Encoding.GetEncoding(page)
                : System.Text.Encoding.GetEncoding(name);
        }
    }

    // A source of code units for the matcher. Implemented by small structs so the JIT
    // specializes Match<T> for each input kind (no interface dispatch in the inner loop).
    internal interface IUnitSource
    {
        /// <summary>Code unit at offset from the start of the current token, or -1 at end of input.</summary>
        int Peek(int offset);
    }

    internal static class LexerRuntime
    {
        // Flat table layout (see Luthor's Compiler.cs):
        //   dfa[0]  newline code unit (for ^ and $), then per state:
        //   accept, bol, eol, n, n x (min, max, target)

        /// <summary>Longest match at the start of <paramref name="text"/>. Returns (symbol or -1, length in units).</summary>
        internal static (int Token, int Length) Match<T>(int[] dfa, ref T text, bool atLineStart) where T : struct, IUnitSource
        {
            int state = 1, accept = -1, length = 0, i = 0;
            bool bol = atLineStart;
            while (true)
            {
                int c = text.Peek(i);                                                          // -1 at end of input
                if (bol && dfa[state + 1] != -1) state = dfa[state + 1];                       // ^
                if ((c == -1 || c == dfa[0]) && dfa[state + 2] != -1) state = dfa[state + 2]; // $
                if (dfa[state] != -1) { accept = dfa[state]; length = i; }
                if (c == -1) break;
                int next = -1, r = state + 4;                                                  // (min, max, target) triples, sorted
                for (int k = 0; k < dfa[state + 3] && c >= dfa[r]; k++, r += 3)
                    if (c <= dfa[r + 1]) { next = dfa[r + 2]; break; }
                if (next == -1) break;
                state = next;
                bol = c == dfa[0];
                i++;
            }
            return (accept, length);
        }

        // ---------------------------------------------------------------- string

        internal static IEnumerable<(long Position, int Symbol, string Text)> Tokenize(int[] dfa, string text)
        {
            if (text is null) throw new ArgumentNullException(nameof(text));
            return TokenizeString(dfa, text);
        }

        static IEnumerable<(long Position, int Symbol, string Text)> TokenizeString(int[] dfa, string text)
        {
            for (int pos = 0; pos < text.Length;)
            {
                var src = new StringSource(text, pos);
                bool atLineStart = pos == 0 || text[pos - 1] == dfa[0];
                var (tok, len) = Match(dfa, ref src, atLineStart);
                if (len == 0) { tok = -1; len = 1; }  // nothing matched (or only an empty match): skip one unit
                yield return (pos, tok, text.Substring(pos, len));
                pos += len;
            }
        }

        struct StringSource : IUnitSource
        {
            readonly string _text; readonly int _pos;
            public StringSource(string text, int pos) { _text = text; _pos = pos; }
            [MethodImpl(MethodImplOptions.AggressiveInlining)]
            public int Peek(int offset) => _pos + offset < _text.Length ? _text[_pos + offset] : -1;
        }

        // ---------------------------------------------------------------- TextReader

        internal static IEnumerable<(long Position, int Symbol, string Text)> Tokenize(int[] dfa, TextReader reader)
        {
            if (reader is null) throw new ArgumentNullException(nameof(reader));
            return TokenizeReader(dfa, reader);
        }

        static IEnumerable<(long Position, int Symbol, string Text)> TokenizeReader(int[] dfa, TextReader reader)
        {
            var window = new CharWindow(reader);
            long pos = 0;
            bool atLineStart = true;
            while (window.Peek(0) != -1)
            {
                var src = new CharWindowSource(window);
                var (tok, len) = Match(dfa, ref src, atLineStart);
                if (len == 0) { tok = -1; len = 1; }
                atLineStart = window.Peek(len - 1) == dfa[0];
                string s = window.Take(len);
                yield return (pos, tok, s);
                pos += len;
            }
        }

        struct CharWindowSource : IUnitSource
        {
            readonly CharWindow _w;
            public CharWindowSource(CharWindow w) => _w = w;
            [MethodImpl(MethodImplOptions.AggressiveInlining)]
            public int Peek(int offset) => _w.Peek(offset);
        }

        // ---------------------------------------------------------------- byte[]

        internal static IEnumerable<(long Position, int Symbol, string Text)> Tokenize(int[] dfa, byte[] data, UnitEncoding encoding, int errorSymbol)
        {
            if (data is null) throw new ArgumentNullException(nameof(data));
            return TokenizeBytes(dfa, data, encoding, errorSymbol);
