            int pos = StartsWith(data, enc.Preamble) ? enc.Preamble.Length : 0;
            bool atLineStart = true;
            while (pos < data.Length)
            {
                var src = new ByteSource(data, pos, unit, enc.BigEndian);
                if (src.Peek(0) == -1)
                {
                    // fewer than UnitSize bytes left: a truncated code unit
                    yield return (pos, errorSymbol, enc.Encoding.GetString(data, pos, data.Length - pos));
                    yield break;
