            for (int k = 0; k < prefix.Length; k++) if (data[k] != prefix[k]) return false;
            return true;
        }

        struct ByteSource : IUnitSource
        {
            readonly byte[] _data; readonly int _pos, _unit; readonly bool _bigEndian;
            public ByteSource(byte[] data, int pos, int unit, bool bigEndian) { _data = data; _pos = pos; _unit = unit; _bigEndian = bigEndian; }
