        [MethodImpl(MethodImplOptions.AggressiveInlining)]
        internal static int ReadUnit(byte[] b, int o, int unit, bool bigEndian)
        {
            switch (unit)
            {
                case 1: return b[o];
                case 2: return bigEndian ? b[o] << 8 | b[o + 1] : b[o] | b[o + 1] << 8;
                default:
                    uint u = bigEndian
                        ? (uint)b[o] << 24 | (uint)b[o + 1] << 16 | (uint)b[o + 2] << 8 | b[o + 3]
                        : b[o] | (uint)b[o + 1] << 8 | (uint)b[o + 2] << 16 | (uint)b[o + 3] << 24;
                    return u > int.MaxValue ? int.MaxValue : (int)u;   // never collide with -1 (end of input)
            }
