        static IEnumerable<(long Position, int Symbol, string Text)> TokenizeStream(int[] dfa, Stream stream, UnitEncoding enc, int errorSymbol)
        {
            var window = new ByteWindow(stream);
            int unit = enc.UnitSize;
            long pos = 0;
