                var (tok, len) = Match(dfa, ref src, atLineStart);
                if (len == 0) { tok = -1; len = 1; }
                atLineStart = src.Peek(len - 1) == dfa[0];
                int bytes = len * unit;
                yield return (pos, tok, window.Take(bytes, enc.Encoding));
                pos += bytes;
            }
        }

        struct ByteWindowSource : IUnitSource
        {
            readonly ByteWindow _w; readonly int _unit; readonly bool _bigEndian;
            public ByteWindowSource(ByteWindow w, int unit, bool bigEndian) { _w = w; _unit = unit; _bigEndian = bigEndian; }
