            public int Peek(int offset) => _unit == 1 ? _w.PeekByte(offset) : _w.PeekUnit(offset, _unit, _bigEndian);
        }
    }

    // A growable window over a TextReader. Index 0 is the start of the current token.
    // Chars are read on demand; Take() consumes from the front. The buffer only grows
    // when a single token (plus its lookahead/overrun) doesn't fit.
    internal sealed class CharWindow
    {
        readonly TextReader _reader;
        char[] _buf;
        int _start, _end;
        bool _eof;

        public CharWindow(TextReader reader, int capacity = 4096)
        {
            _reader = reader ?? throw new ArgumentNullException(nameof(reader));
            _buf = new char[capacity];
        }

        /// <summary>Char at offset from the token start, or -1 at end of input.</summary>
        [MethodImpl(MethodImplOptions.AggressiveInlining)]
        public int Peek(int offset)
            => _start + offset < _end ? _buf[_start + offset] : PeekSlow(offset);

        [MethodImpl(MethodImplOptions.NoInlining)]
        int PeekSlow(int offset)
        {
            while (_start + offset >= _end)
            {
                if (_eof) return -1;
                Fill();
            }
            return _buf[_start + offset];
        }

        void Fill()
        {
            if (_end == _buf.Length)
            {
                if (_start == 0)
                {
                    Array.Resize(ref _buf, _buf.Length * 2);
                }
                else
                {
                    int count = _end - _start;
                    Array.Copy(_buf, _start, _buf, 0, count);   // overlap-safe
                    _start = 0;
                    _end = count;
                }
            }
            int n = _reader.Read(_buf, _end, _buf.Length - _end);
            if (n == 0) _eof = true;
            else _end += n;
        }

        public string Take(int length)
        {
            string s = new string(_buf, _start, length);
            _start += length;
            return s;
        }
    }

    // The byte counterpart of CharWindow, over a Stream.
    internal sealed class ByteWindow
    {
        readonly Stream _stream;
        byte[] _buf;
        int _start, _end;
        bool _eof;

        public ByteWindow(Stream stream, int capacity = 4096)
        {
            _stream = stream ?? throw new ArgumentNullException(nameof(stream));
            _buf = new byte[capacity];
        }

        /// <summary>Bytes currently buffered past the token start.</summary>
        public int Available => _end - _start;

        /// <summary>Byte at offset from the token start, or -1 at end of input.</summary>
        [MethodImpl(MethodImplOptions.AggressiveInlining)]
        public int PeekByte(int offset)
            => _start + offset < _end ? _buf[_start + offset] : PeekSlow(offset);

        /// <summary>Code unit <paramref name="index"/> (of <paramref name="unit"/> bytes) from the token start, or -1 if incomplete.</summary>
        public int PeekUnit(int index, int unit, bool bigEndian)
        {
            int o = index * unit;
            if (PeekByte(o + unit - 1) == -1) return -1;
            return LexerRuntime.ReadUnit(_buf, _start + o, unit, bigEndian);
        }

        public bool StartsWith(byte[] prefix)
        {
            if (prefix.Length == 0) return false;
            for (int k = 0; k < prefix.Length; k++) if (PeekByte(k) != prefix[k]) return false;
            return true;
        }

        [MethodImpl(MethodImplOptions.NoInlining)]
        int PeekSlow(int offset)
        {
            while (_start + offset >= _end)
            {
                if (_eof) return -1;
                Fill();
            }
            return _buf[_start + offset];
        }

        void Fill()
        {
            if (_end == _buf.Length)
            {
                if (_start == 0)
                {
                    Array.Resize(ref _buf, _buf.Length * 2);
                }
                else
                {
                    int count = _end - _start;
                    Array.Copy(_buf, _start, _buf, 0, count);
                    _start = 0;
                    _end = count;
                }
            }
            int n = _stream.Read(_buf, _end, _buf.Length - _end);
            if (n == 0) _eof = true;
            else _end += n;
        }

        public void Skip(int length) => _start += length;

        public string Take(int length, Encoding encoding)
        {
            string s = encoding.GetString(_buf, _start, length);
            _start += length;
            return s;
        }
    }
